mapper.select:
    select count(1) from sys_user_role a where a.role_id=#{roleId}
	AND NOT EXISTS (
		SELECT 1 FROM sys_user b WHERE a.user_id=b.user_id AND b.DEL_FLAG=2
	)

    select count(1) from sys_user_role a where a.role_id in

		#{item}

	AND NOT EXISTS (
		SELECT 1 FROM sys_user b WHERE a.user_id=b.user_id AND b.DEL_FLAG=2
	)
